enum class Suit(val key: String) {
    CLUBS("clubs"), DIAMONDS("diamonds"), HEARTS("hearts"), SPADES("spades");
}

fun parse(raw: String): Suit =
    Suit.entries.firstOrNull { it.key == raw } ?: error("unknown suit: $raw")

fun label(s: Suit): String = when (s) {      // compiler checks all entries
    Suit.CLUBS -> "Clubs"; Suit.DIAMONDS -> "Diamonds"
    Suit.HEARTS -> "Hearts"; Suit.SPADES -> "Spades"
}
